import styled from '@emotion/styled';

export const StyledZoneMaturityControlsContainer = styled.div({
  width: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'flex-end',
  gap: '16px',
  marginBottom: '8px',
});

export const StyledZoneMaturityFlexContainer = styled.div({
  display: 'flex',
  flexDirection: 'row',
});

export const StyledZoneMaturityLegendContainer = styled.div({
  paddingLeft: '16px',
  borderTop: '1px solid #1414141F',
});
